<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{PakistanErpRepository,SettingsRepository,StudentRepository};use App\Services\CredentialService;use App\Support\Flash;
final class GuardiansController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():PakistanErpRepository{return new PakistanErpRepository($this->app->database());}
public function index(Request$q):Response{return$this->view('guardians/index',['pageTitle'=>'Parents & Guardians','activeMenu'=>'students','activeSubmenu'=>'guardians','institute'=>(new SettingsRepository($this->app->database()))->institute(),'guardians'=>$this->r()->guardians($this->i()),'students'=>(new StudentRepository($this->app->database()))->paginate($this->i(),'',null),'temporaryCredential'=>$this->app->session()->pull('temporary_credential')]);}
public function store(Request$q):Response{$name=trim((string)$q->input('name'));$mobile=trim((string)$q->input('mobile'));if($name===''||$mobile===''){Flash::add('error','Guardian name and mobile are required.');return Response::redirect(url('/admin/guardians'));}$existing=(int)$q->input('id');if($existing&&!$this->r()->guardian($existing,$this->i()))return Response::html('Guardian not found',404);$id=$this->r()->saveGuardian($existing?:null,$this->i(),['name'=>$name,'relationship'=>trim((string)$q->input('relationship'))?:'Guardian','cnic'=>trim((string)$q->input('cnic'))?:null,'mobile'=>$mobile,'email'=>trim((string)$q->input('email'))?:null,'address'=>trim((string)$q->input('address'))?:null,'status'=>'active']);$this->r()->syncGuardianChildren($id,$this->i(),(array)$q->input('students',[]));$this->r()->audit($this->i(),(int)user()['id'],$existing?'guardian.updated':'guardian.created','guardian',$id);Flash::add('success',$existing?'Guardian updated.':'Guardian saved and linked.');return Response::redirect(url('/admin/guardians'));}
public function deactivate(Request$q):Response{$id=(int)$q->route('id');if($this->r()->deactivateGuardian($id,$this->i())){$this->r()->audit($this->i(),(int)user()['id'],'guardian.deactivated','guardian',$id);Flash::add('success','Guardian access deactivated; linked student history was preserved.');}else Flash::add('error','Guardian not found.');return Response::redirect(url('/admin/guardians'));}
public function login(Request$q):Response{try{$x=(new CredentialService($this->app->database()))->create('guardian',(int)$q->input('guardian_id'),$this->i(),(string)$q->input('email'),(int)user()['id'],trim((string)$q->input('password'))?:null);$this->app->session()->flash('temporary_credential',$x['temporary_password']);Flash::add('success','Parent login created.');}catch(\Throwable$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/guardians'));}
public function loginStatus(Request$q):Response{$level=(string)$q->input('status');$labels=['active'=>'Parent login activated.','suspended'=>'Parent login suspended.','disabled'=>'Parent login blocked.'];if(!isset($labels[$level]))return Response::html('Invalid status',422);try{(new \App\Services\AccountAccess($this->app->database()))->setManual('guardian',(int)$q->route('id'),$this->i(),$level,trim((string)$q->input('reason')));Flash::add('success',$labels[$level]);}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/guardians'));}
public function deleteLogin(Request$q):Response{try{(new CredentialService($this->app->database()))->delete('guardian',(int)$q->route('id'),$this->i());Flash::add('success','Parent login deleted.');}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/guardians'));}
}
